func cliArgsFromMCP(args map[string]any, blocked map[string]bool) []string {
	keys := make([]string, 0, len(args))
	for k := range args {
		if strings.Contains(k, "=") {
			continue
		}
		if blocked[k] || confirmationBypassRootFlags[k] {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var out []string
	for _, k := range keys {
		v := args[k]
		// Join values onto the flag so a value starting with -- cannot be
		// re-parsed as its own flag (bool flags do not consume the next token).
		switch tv := v.(type) {
		case bool:
			if tv {
				out = append(out, "--"+k)
			}
		case float64:
			out = append(out, "--"+k+"="+strconv.FormatFloat(tv, 'f', -1, 64))
		case string:
			if tv != "" {
				out = append(out, "--"+k+"="+tv)
			}
		case []any:
			// One --flag=value per item, including "". Comma-joining would
			// collapse a stringArray (it does not split on commas) into one
			// value, and dropping an empty item would leave a nonempty default.
			for _, item := range tv {
				if item == nil {
					continue
				}
				part := fmt.Sprintf("%v", item)
				out = append(out, "--"+k+"="+part)
			}
		default:
			if v != nil {
				out = append(out, "--"+k+"="+fmt.Sprintf("%v", v))
			}
		}
	}
	return out
}

// SplitShellArgs whitespace-splits with shell-style quote preservation.
func SplitShellArgs(s string) []string {
	var tokens []string
	var cur []rune
	inSingleQuote := false
	inDoubleQuote := false
	escaped := false
	for _, r := range s {
		switch {
		case escaped:
			cur = append(cur, r)
			escaped = false
		case r == '\\' && !inSingleQuote:
			escaped = true
		case r == '\'' && !inDoubleQuote:
			inSingleQuote = !inSingleQuote
		case r == '"' && !inSingleQuote:
			inDoubleQuote = !inDoubleQuote
		case (r == ' ' || r == '\t') && !inSingleQuote && !inDoubleQuote:
			if len(cur) > 0 {
				tokens = append(tokens, string(cur))
				cur = cur[:0]
			}
		default:
			cur = append(cur, r)
		}
	}
	if escaped {
		cur = append(cur, '\\')
	}
	if len(cur) > 0 {
		tokens = append(tokens, string(cur))
	}
	return tokens
}

