// etsy-ext: byte-preserving internal mirror path; exported string API remains compatible.
func runCLICommand(ctx context.Context, binPath string, args []string, raw bool) (CLICommandResult, error) {
	cmd := exec.CommandContext(ctx, binPath, args...) // #nosec G204 -- trusted companion CLI path, args pre-tokenized.
	// os.Getenv returns the first duplicate, so an inherited marker has to
	// be replaced. A nil Env would inherit the parent and could not force it.
	cmd.Env = mcpChildEnviron()
	stdout := newStdoutCapture() // etsy-ext: stderr alone keeps the historical small cap
	stderr := newCappedCapture()
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	err := cmd.Run()
	stdoutText := "" // etsy-ext: avoid allocating a stdout string for mirrored success.
	if !raw || err != nil {
		stdoutText = stdout.String()
	}
	result := CLICommandResult{
		Stdout:         stdoutText,
		StdoutBytes:    stdout.total, // etsy-ext: true byte count and overflow
		StdoutOverflow: stdout.total > bound.MirrorCaptureMax,
		StderrHints:    stderrHintLines(stderr.String()),
	}
	if raw && err == nil {
		result.rawStdout = stdout.data
	} // etsy-ext: transfer retained bytes.
	if err != nil {
		stderrText := strings.TrimSpace(stderr.String())
		stdoutTrim := strings.TrimSpace(stdoutText)
		result.Stderr = stderrText
		detail := cliFailureDetail(stdoutTrim, stderrText)
		if detail == "" {
			return result, fmt.Errorf("cli %s: %w", binPath, err)
		}
		return result, fmt.Errorf("cli %s: %w (%s)", binPath, err, bound.Text(detail))
	}
	return result, nil
}

// Mirrored CLI children do not authenticate the MCP listener. Copying this
// bearer into every command environment only exposes it.
const mcpHTTPTokenEnvVar = "ETSY_MCP_HTTP_TOKEN"

func mcpChildEnviron() []string {
	base := os.Environ()
	env := make([]string, 0, len(base)+1)
	for _, entry := range base {
		if mcpChildEnvDropped(entry) {
			continue
		}
		env = append(env, entry)
	}
	return append(env, cliutil.MCPChildEnvVar+"=1")
}

func mcpChildEnvDropped(entry string) bool {
	key, _, ok := strings.Cut(entry, "=")
	if !ok {
		return false
	}
	if key == cliutil.MCPChildEnvVar {
		return true
	}
	return strings.EqualFold(key, mcpHTTPTokenEnvVar)
}

func cliFailureDetail(stdout, stderr string) string {
	switch {
	case stdout != "" && stderr != "":
		return "stdout: " + stdout + "\nstderr: " + stderr
	case stderr != "":
		return "stderr: " + stderr
	case stdout != "":
		return "output: " + stdout
	default:
		return ""
	}
}

func stderrHintLines(stderr string) []string {
	var hints []string
	for _, rawLine := range strings.Split(stderr, "\n") {
		for _, segment := range strings.Split(rawLine, "\r") {
			line := strings.TrimSpace(segment)
			lower := strings.ToLower(line)
			if strings.HasPrefix(lower, "hint:") || strings.HasPrefix(lower, "warning:") {
				hints = append(hints, line)
			}
		}
	}
	return hints
}

// etsy-ext: platform limits leave room below Linux MAX_ARG_STRLEN and Windows CreateProcess.
const mirrorUnixArgMax = 122880
const mirrorWindowsCommandMax = 31744

func mirrorArgName(arg string) string {
	if strings.HasPrefix(arg, "--") {
		name, _, _ := strings.Cut(arg, "=")
		return "argument " + name
	}
	return "positional argument"
}

// etsy-ext: local copy of syscall.EscapeArg's Windows algorithm: quote empty
// args and whitespace; escape quotes by doubling preceding backslashes plus
// one, and double trailing backslashes before the closing quote.
func mirrorWindowsEscape(arg string) string {
	if arg == "" {
		return `""`
	}
	quote := strings.ContainsAny(arg, " \t")
	var out strings.Builder
	if quote {
		out.WriteByte('"')
	}
	slashes := 0
	for _, c := range arg {
		if c == '\\' {
			slashes++
			continue
		}
		if c == '"' {
			out.WriteString(strings.Repeat("\\", slashes*2+1))
		} else {
			out.WriteString(strings.Repeat("\\", slashes))
		}
		slashes = 0
		out.WriteRune(c)
	}
	if quote {
		slashes *= 2
	}
	out.WriteString(strings.Repeat("\\", slashes))
	if quote {
		out.WriteByte('"')
	}
	return out.String()
}

// etsy-ext: pure OS-parametrised pre-exec validation, independent of cursor state.
func checkMirrorArgLimits(goos string, argv []string) error {
	total, largest := 260, ""
	for _, arg := range argv {
		if len(arg) > len(largest) {
			largest = arg
		}
		if goos != "windows" && len(arg) > mirrorUnixArgMax {
			return fmt.Errorf("%s is %d bytes, over the %d-byte per-argument limit for this platform; shorten the value", mirrorArgName(arg), len(arg), mirrorUnixArgMax)
		}
		total += len(mirrorWindowsEscape(arg))
		total++ // include the space after the executable allowance, too.
	}
	if goos == "windows" && total > mirrorWindowsCommandMax {
		return fmt.Errorf("%s is the largest argument; escaped command line is %d bytes, over the %d-byte limit for this platform; shorten the value", mirrorArgName(largest), total, mirrorWindowsCommandMax)
	}
	return nil
}

// etsy-ext: one process-wide semaphore, configured once at mirror registration.
var mirrorAdmission struct {
	sync.Once
	limiter *mirrorLimiter
}

type mirrorLimiter struct {
	local     *mirrorLimiter // etsy-ext: separate local read pool.
	localRead bool
	slots     chan struct{}
	timeout   time.Duration
}

func newMirrorLimiter() *mirrorLimiter {
	mirrorAdmission.Do(func() { mirrorAdmission.limiter = configuredMirrorLimiter() })
	return mirrorAdmission.limiter
}

// etsy-ext: isolate configuration parsing so boundary tests avoid global reset.
func configuredMirrorLimiter() *mirrorLimiter {
	n := 4
	if raw := strings.TrimSpace(os.Getenv("PP_MCP_MAX_CONCURRENCY")); raw != "" {
		v, err := strconv.Atoi(raw)
		if err != nil || v < 1 || v > 32 {
			fmt.Fprintln(os.Stderr, "PP_MCP_MAX_CONCURRENCY invalid; using default 4")
		} else {
			n = v
		}
	}
	wait := 20 * time.Second
	if raw := strings.TrimSpace(os.Getenv("PP_MCP_QUEUE_TIMEOUT")); raw != "" {
		v, err := time.ParseDuration(raw)
		if err != nil || v < time.Millisecond || v > 5*time.Minute {
			fmt.Fprintln(os.Stderr, "PP_MCP_QUEUE_TIMEOUT invalid; using default 20s")
		} else {
			wait = v
		}
	}
	return &mirrorLimiter{slots: make(chan struct{}, n), timeout: wait, local: &mirrorLimiter{slots: make(chan struct{}, 4*n), timeout: wait, localRead: true}} // etsy-ext: independent local capacity.
}

func (l *mirrorLimiter) acquire(ctx context.Context) (func(), error) {
	// etsy-ext: uncontended admission needs no timer.
	select {
	case l.slots <- struct{}{}:
		return func() { <-l.slots }, nil
	default:
	}
	timer := time.NewTimer(l.timeout)
	defer timer.Stop()
	select {
	case l.slots <- struct{}{}:
		return func() { <-l.slots }, nil
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-timer.C:
		if l.localRead {
			return nil, fmt.Errorf("busy: %d local read calls in flight; retry", len(l.slots))
		} // etsy-ext: identify the independent pool.
		return nil, fmt.Errorf("busy: %d mirror calls in flight (limit PP_MCP_MAX_CONCURRENCY); retry", len(l.slots))
	}
}

// etsy-ext: JSON containers cannot be Cobra help; avoid scanning their full body.
func mirrorJSONLike(data []byte) bool {
	data = bytes.TrimSpace(data)
	return len(data) > 0 && (data[0] == '{' || data[0] == '[')
}
